let current = null, previous = 'w-list', formDirty = false;
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name='InfoCircle')=>(window.DESIGN_ICONS?.[name]||window.DESIGN_ICONS?.InfoCircle||'');
const btn=(label,to,cls='',disabled=false)=>`<button type="button" class="btn ${cls}" ${to?`${to.startsWith('!')?'data-action':'data-go'}="${e(to.replace(/^!/,''))}"`:''} ${disabled?'disabled':''}>${label}</button>`;
const badge=(label,tone='',dot=false)=>`<span class="badge ${tone}">${dot?'<span class="dot"></span>':''}${label}</span>`;
const tags=(list,bit=false)=>`<div class="tag-row">${list.map(t=>`<span class="tag ${bit?'bit':''}">${e(t)}</span>`).join('')}</div>`;
const notice=(title,text='',tone='blue',action='')=>`<div class="notice ${tone}">${icon(tone==='green'?'CheckCircle':tone==='red'?'ErrorCircle':'InfoCircle')}<div><strong>${title}</strong>${text?`<p>${text}</p>`:''}</div>${action?`<div class="notice-actions">${action}</div>`:''}</div>`;
const field=(label,value='',opts={})=>`<div class="field ${opts.full?'full':''}"><label>${opts.required?'<b>*</b>':''}${label}</label>${opts.area?`<textarea class="input ${opts.error?'error':''}" placeholder="${e(opts.placeholder||'')}" ${opts.readonly?'readonly':''}>${e(value)}</textarea>`:opts.options?`<select class="input" ${opts.route?`data-route-change="${e(opts.route)}"`:''}>${opts.options.map(o=>`<option ${String(o)===String(value)?'selected':''}>${e(o)}</option>`).join('')}</select>`:`<input class="input ${opts.error?'error':''}" type="${opts.type||'text'}" value="${e(value)}" placeholder="${e(opts.placeholder||'')}" ${opts.readonly?'readonly':''} ${opts.required?'required':''} ${opts.name?`name="${e(opts.name)}"`:''}>`}${opts.error?`<div class="error-text">${opts.error}</div>`:''}${opts.hint?`<small>${opts.hint}</small>`:''}</div>`;
const facts=(pairs,two=false)=>`<dl class="facts ${two?'two-col':''}">${pairs.map(p=>`<dt>${p[0]}</dt><dd>${p[1]}</dd>`).join('')}</dl>`;
const section=(title,body,scope='')=>`<section class="section"><h3>${title}${scope?`<span class="scope-label">${scope}</span>`:''}</h3>${body}</section>`;
const objectStrip=(title='B站主号 · 上海01',sub='系统窗口 ID 328　·　BitBrowser ID 8f3a…a962',kind='Desktop')=>`<div class="object-strip"><span class="object-mark">${icon(kind)}</span><div><strong>${title}</strong><small>${sub}</small></div></div>`;
const resultHead=(title,text,tone='green')=>`<div class="result-head"><div class="result-icon ${tone}">${icon(tone==='green'?'CheckCircle':tone==='red'?'ErrorCircle':'InfoCircle')}</div><h2>${title}</h2><p>${text}</p></div>`;
const resultStats=items=>`<div class="result-stats">${items.map(([n,l])=>`<div><strong>${n}</strong>${l}</div>`).join('')}</div>`;
function dialog(title,body,footer,wide=''){return `<div class="overlay"><section class="dialog ${wide}" role="dialog" aria-modal="true" aria-label="${e(title)}"><header class="dialog-header">${title}<button class="close" data-action="close" aria-label="关闭">×</button></header><div class="dialog-body">${body}</div><footer class="dialog-footer">${footer}</footer></section></div>`}
function drawer(title,body,footer='',wide=false){return `<div class="overlay"><section class="drawer ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${e(title)}"><header class="drawer-header">${title}<button class="close" data-action="close" aria-label="关闭">×</button></header><div class="drawer-body">${body}</div>${footer?`<footer class="drawer-footer">${footer}</footer>`:''}</section></div>`}
