function shell(content,mod='window',web=false){return `<div class="app"><aside class="sidebar"><div class="brand"><span class="logo-crop"><img src="assets/logo.png" alt=""></span><div><strong>起飞</strong><small>内容运营平台</small></div></div><div class="nav-heading">工作空间</div><button class="nav-item" data-action="home">${icon('Home')}工作台</button><div class="nav-item">${icon('Browse')}内容挖掘</div><div class="nav-item">${icon('Video')}内容生产</div><div class="nav-item">${icon('Send')}运营执行</div><div class="nav-heading">运营资源</div><button class="nav-item sub ${mod==='window'?'active':''}" data-go="w-list">浏览器窗口</button><button class="nav-item sub ${mod==='proxy'?'active':''}" data-go="p-list">代理管理</button><div class="nav-item sub">社媒账号</div><div class="nav-heading">管理与设置</div><div class="nav-item">${icon('ChartBar')}数据分析</div><div class="nav-item">${icon('Setting')}系统管理</div><div class="side-bottom">${badge(web?'Cloud Web':'Desktop · 本机执行',web?'':'blue')}<div>当前团队 · 星河运营组</div><div style="margin-top:7px">WT Media　/　工作空间</div></div></aside><div class="app-right"><header class="topbar"><div class="breadcrumb">运营资源 <span>／　${mod==='window'?'浏览器窗口':'代理管理'}</span></div><div class="top-right">${web?badge('Cloud Web'):badge('本机环境可用','green',true)}${icon('Notification')}<span class="avatar">林</span><span>${web?'陈以宁 · 高级运营':'林予安 · 普通运营'}</span>${icon('ChevronDown')}</div></header><main class="main-content">${content}</main></div></div>`}
function stats(mod){const list=mod==='window'?[['浏览器窗口','128','Window','当前主账号下的Cloud镜像'],['比特自管','42','Desktop','不占系统代理额度'],['系统管理','86','Link','正式关联系统代理'],['需处理异常','4','ErrorCircle','不一致 1 · 到期 1 · 缺失 1 · 待确认 1']]:[['代理资源','24','Link','独立台账 · 按授权范围'],['可分配代理','18','CheckCircle','正常且未到期、未满额'],['窗口配额','61 / 96','Desktop','仅统计系统正式关系'],['需关注资源','6','ErrorCircle','即将到期 3 · 检测异常 3']];return `<div class="stats">${list.map(([l,n,i,t])=>`<div class="stat"><div><label>${l}</label><strong>${n}</strong><div class="stat-note">${t}</div></div><div class="stat-icon">${icon(i)}</div></div>`).join('')}</div>`}
function windowTable(selected=false,cloud=false){return `<div class="table-wrap"><table class="resource-table"><thead><tr><th style="width:32px"><input class="check" type="checkbox" ${selected?'checked':''} data-action="select"></th><th>ID / 窗口信息</th><th>BitBrowser分组</th><th>代理管理方式</th><th>实际代理 / 资源</th><th>业务 / 运行</th><th>最近同步</th><th>操作</th></tr></thead><tbody>${windowRows.map((r,i)=>`<tr data-search="${e(r.join(' '))}"><td><input class="check" type="checkbox" ${selected&&i<3?'checked':''} data-action="select"></td><td><div class="name-cell">${r[0]}　${r[1]}<small>Bit ID　8f3a…${['a962','b180','c241','d509','f015','e313','c810','a276'][i]}</small></div></td><td><div>${r[2]}</div><div style="margin-top:5px">${tags(r[8],true)}</div></td><td>${badge(r[3]==='system'?'系统管理':'比特自管',r[3]==='system'?'blue':'')}<div class="tiny muted" style="margin-top:5px">${r[3]==='system'?'配额已占用':'系统配额不占用'}</div></td><td><span class="mono">${r[5]}</span><div class="tiny muted">${r[3]==='system'?r[4]:'BitBrowser实际配置'}</div>${r[6]==='mismatch'?badge('代理配置不一致','orange'):r[6]==='expired'?badge('系统代理已到期','red'):r[6]==='missing'?badge('本机窗口缺失','red'):''}</td><td><div>${badge('启用','green')}</div><div class="tiny ${r[7]==='active'?'':'muted'}" style="margin-top:5px">${r[6]==='missing'?'运行未知':r[7]==='active'?'● 已打开':'○ 已关闭'}</div></td><td class="tiny subtle">10-27 14:32<br><span class="muted">${cloud?'Cloud保存结果':'本机实读'}</span></td><td><div class="row-actions">${btn('详情',r[3]==='self'?'w-detail-self':r[6]==='mismatch'?'w-detail-mismatch':'w-detail-managed','text')}${!cloud?btn(r[7]==='active'?'关闭':'打开','!window','text',r[6]==='missing')+btn(r[6]==='mismatch'?'处理异常':'管理代理',r[6]==='mismatch'?'w-mismatch':'w-mode','text')+btn('更多','!more-window','text'):btn('运营备注','w-note','text')}</div></td></tr>`).join('')}</tbody></table></div>`}
function proxyTable(cloud=false){return `<div class="table-wrap"><table class="resource-table"><thead><tr><th><input type="checkbox" class="check" data-action="select-proxy"></th><th>代理资源 / 地址</th><th>地区 / 供应商</th><th>来源 / 标签</th><th>状态 / 检测</th><th>窗口配额</th><th>到期时间</th><th>操作</th></tr></thead><tbody>${proxyRows.map((r,i)=>`<tr data-search="${e(r.join(' '))}"><td><input type="checkbox" class="check" data-action="select-proxy"></td><td><div class="name-cell">${r[1]}<small>${r[0]}　·　${r[2]}</small></div><div class="mono" style="margin-top:4px">${r[3]}</div></td><td>${r[4]}<div class="tiny muted">${r[5]}</div></td><td>${badge(r[6]==='api'?'动态 API':'静态地址',r[6]==='api'?'blue':'')}<div style="margin-top:6px">${tags(r[11])}</div></td><td>${badge(r[7]==='expired'?'已到期':r[7]==='paused'?'已停用':'启用',r[7]==='expired'?'red':r[7]==='paused'?'':'green')}<div class="tiny ${r[7]==='fail'?'inline-error':'muted'}" style="margin-top:5px">${r[7]==='ok'?'检测正常':r[7]==='fail'?'连接失败':r[7]==='unknown'?'尚未检测':'最近检测 10-26'}</div></td><td><strong style="font-weight:500">${r[8]} / ${r[9]}</strong><div class="progress" style="width:75px;height:3px;margin:7px 0"><span style="width:${100*r[8]/r[9]}%;${r[8]===r[9]?'background:var(--orange)':''}"></span></div><span class="tiny muted">剩余 ${r[9]-r[8]} 个</span></td><td class="tiny ${r[7]==='expired'?'inline-error':'subtle'}">${r[10]}<br>${r[7]==='expired'?'已过期':i===5?'12天后到期':'有效'}</td><td><div class="row-actions">${btn('详情',r[7]==='expired'?'p-expired':r[6]==='api'?'p-detail-api':'p-detail','text')}${!cloud?btn('检测','p-checking','text',r[7]==='paused'):''}${btn('编辑','p-edit','text')}${btn('配额','p-quota','text')}${btn('删除',r[8]?'p-delete-blocked':'p-delete','text danger-text')}</div></td></tr>`).join('')}</tbody></table></div>`}
function pagination(mod){return `<div class="pagination"><span>共 ${mod==='window'?128:24} 条　·　每页 10 条</span><div class="page-numbers"><span>10 条 / 页　⌄　</span><button class="page-number" data-action="page">‹</button><button class="page-number selected" data-action="page">1</button><button class="page-number" data-action="page">2</button><button class="page-number" data-action="page">3</button><span>…</span><button class="page-number" data-action="page">${mod==='window'?13:3}</button><button class="page-number" data-action="page">›</button></div></div>`}
function listPage(scene){const mod=scene.module,web=scene.state==='web',isW=mod==='window',state=scene.view==='list'?scene.state:'default';let actions=isW?(!web?btn(icon('Refresh')+'同步本机窗口','w-sync-issues')+btn(icon('Add')+'新建窗口','w-create','primary'):''):btn(icon('Upload')+'批量导入','p-import')+btn(icon('Add')+'新增代理','p-create','primary');if(state==='permission')actions='';let head=`<div class="page-header"><div><h1 class="page-title">${isW?'浏览器窗口':'代理管理'}</h1><div class="description">${isW?'管理窗口环境与代理关系，让实际配置和运营事实保持清晰。':'维护代理资源、可用性与窗口配额。代理绑定和本机变更请在浏览器窗口中完成。'}</div></div><div class="actions">${actions}</div></div>`;
let alerts='';if(web)alerts=notice(isW?'当前展示Cloud已保存的窗口镜像':'当前为Cloud资源管理视图',isW?'本机同步、打开窗口和BitBrowser字段修改请由普通运营在Desktop完成。':'代理资料和配额可按权限维护；本机检测、动态提取与窗口写入需在授权Desktop执行。');if(state==='offline')alerts=notice('BitBrowser未运行，当前无法执行本机操作','Cloud已保存的台账仍可查看。请启动BitBrowser并使用已绑定的主账号登录后重试。','orange',btn('重新检测','w-sync-issues','small'));
let filters=`<div class="filters"><div class="field wide"><label>综合搜索</label><input class="input" data-filter placeholder="${isW?'窗口名称 / ID / 备注 / 标签':'名称 / Host / 供应商 / 备注'}" ${state==='noresult'?'value="上海未分配测试窗口"':''}></div>${field(isW?'代理管理方式':'地区','全部',{options:isW?['全部','比特自管','系统管理']:['全部','上海','广州','杭州']}).replace('class="field "','class="field medium"')}${field(isW?'异常状态':'资源状态','全部',{options:isW?['全部','代理配置不一致','代理到期','本机缺失','结果待确认']:['全部','启用','停用','已到期']}).replace('class="field "','class="field medium"')}${field(isW?'BitBrowser分组':'供应商','全部',{options:isW?['全部','主力账号组','备用账号组']:['全部','星云网络','云桥网络']}).replace('class="field "','class="field medium"')}<div class="actions">${btn('查询','!filter','primary')}${btn('重置',isW?'w-list':'p-list')}</div></div>`;
let table= isW?windowTable(state==='selected',web):proxyTable(web);if(state==='selected')table=`<div class="selection"><span>已选择 <strong>3</strong> 个窗口　<span class="muted">不同管理方式可分别处理</span></span><div class="actions">${btn('绑定系统代理','w-batch-bind','small')}${btn('修改分组','w-batch-edit','small')}${btn('改为比特自管','w-batch-self','small')}${btn('取消选择','w-list','text')}</div></div>`+table;
if(['empty','noresult','error','permission'].includes(state)){const options={empty:[isW?'还没有浏览器窗口':'还没有代理资源',isW?'同步已登录BitBrowser中的窗口，或新建一个窗口开始准备账号环境。':'添加已有代理或批量导入，检测正常后即可在浏览器窗口中分配。',isW?'Desktop':'Link',isW?btn('同步本机窗口','w-sync','primary')+btn('新建窗口','w-create'):btn('新增代理','p-create','primary')+btn('批量导入','p-import')],noresult:['没有找到符合条件的窗口','尝试调整管理方式、异常状态或关键词，不会影响已有窗口数据。','Search',btn('清除筛选','w-list')],error:['窗口列表加载失败','未能获取Cloud保存的窗口数据。请检查网络连接后重试，当前筛选已保留。','ErrorCircle',btn('重新加载','w-list','primary')],permission:['你没有查看此资源的权限','当前账号无浏览器窗口查看权限。请使用获授权的账号，或联系管理员确认访问范围。','LockOn',btn('返回工作台','!home')]};const[t,d,i,a]=options[state];table=`<div class="empty-state"><div class="empty-symbol">${icon(i)}</div><h3>${t}</h3><p>${d}</p><div class="actions">${a}</div></div>`}
if(state==='loading')table=`<table><thead><tr>${['窗口信息','管理方式','实际代理','业务状态','最近同步','操作'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${Array.from({length:8},(_,i)=>`<tr>${Array.from({length:6},(_,j)=>`<td style="height:64px"><span class="skeleton" style="width:${j===0?135:j===2?150:72}px"></span></td>`).join('')}</tr>`).join('')}</tbody></table>`;
return shell(head+alerts+(state!=='permission'?stats(mod):'')+`<section class="panel">${state!=='permission'?filters:''}${table}${!['permission','empty','noresult','error'].includes(state)?pagination(mod):''}</section>`,mod,web)}

function windowDetail(s){const self=s.state==='self',bad=s.state==='mismatch',id=self?'329':bad?'332':'328',name=self?'百度 · 上海02':bad?'B站备用 · 华东03':'B站主号 · 上海01';let content=objectStrip(name,`系统窗口 ID ${id}　·　BitBrowser ID 8f3a28b697e44cb0a962`);if(bad)content+=notice('系统代理配置与BitBrowser实际配置不一致','已保留原系统管理关系。该窗口的账号执行环境需要确认；未自动创建或替换代理资源。','orange');content+=section('BitBrowser窗口信息',facts([['窗口名称',name],['Profile ID','<span class="mono">8f3a28b697e44cb0a962</span>'],['比特序号','1028'],['BitBrowser分组',self?'主力账号组':'备用账号组'],['BitBrowser标签',tags(self?['百度','华东']:['B站','华东'],true)],['BitBrowser备注',self?'人工登录已完成，保留现有环境':'专用创作窗口，请保持指纹配置不变'],['本机运行状态',badge('已打开','green',true)],['最近同步','2026-10-27 14:32:08']]),'以BitBrowser实际值为准');content+=section('代理管理与实际配置',facts([['管理方式',badge(self?'比特自管':'系统管理',self?'':'blue')],['实际代理',`<span class="mono">${self?'http://198.51.100.24:8080':bad?'socks5://203.0.113.66:1080':'socks5://203.0.113.18:1080'}</span>`],['系统代理资源',self?'未建立系统代理关系':`沪线 · 静态${bad?'05':'03'}　<span class="muted">PX-00${bad?'5':'3'}</span>`],['一致性',self?'不进行系统资源配置比对':badge(bad?'配置不一致':'已读回一致',bad?'orange':'green')],['配额占用',self?'不占用系统代理配额':'占用 1 个窗口额度']]),self?'BitBrowser自行维护':'正式关系由WT Media管理');content+=section('WT Media运营信息',facts([['授权用户','林予安　<span class="muted">星河运营组</span>'],['业务状态',badge('启用','green')],['关联媒体账号',self?'百度 · 星河游戏资讯　<span class="muted">账号 ID 216</span>':'B站 · 星河玩游戏　<span class="muted">账号 ID 208</span>'],['业务标签',tags(['主力运营','日常发布'])],['运营备注','每日发布前检查账号状态；请勿与测试窗口混用。']]),'Cloud正式运营事实');return drawer('浏览器窗口详情',content)}
function createWindow(s){const err=s.state==='error';return dialog('新建浏览器窗口',notice('在当前BitBrowser主账号下创建真实窗口','创建后读取真实Profile并同步镜像；授权与运营信息不会由扫描覆盖。')+`<div class="form-grid">${field('窗口名称',err?'':'B站新号 · 上海05',{required:true,full:true,placeholder:'为窗口填写便于辨认的名称',error:err?'请输入窗口名称':''})}${field('BitBrowser分组','主力账号组',{required:true,options:['主力账号组','备用账号组','华南运营组']})}${field('创建归属','当前授权用户 · 林予安',{readonly:true})}${field('BitBrowser标签','B站，华东',{full:true,hint:'写入BitBrowser；与账号业务标签独立。'})}${field('BitBrowser备注','用于B站日常运营，首次使用后人工登录。',{area:true,full:true})}</div><div class="divider"></div><div class="form-heading">初始代理方式</div><div class="radio-cards"><label class="radio-card selected"><input type="radio" checked name="create-mode"><span><strong>比特自管</strong><small>使用BitBrowser初始代理配置，不建立系统资源关系。</small></span></label><label class="radio-card"><input type="radio" name="create-mode"><span><strong>系统管理</strong><small>创建成功后选择系统代理并写入验证。</small></span></label></div><div class="scene-hint">此处不填写平台UID、Cookie或账号登录状态。</div>`,cancel()+btn('创建并同步','!create-window','primary'))}
function created(){return dialog('窗口创建结果',resultHead('窗口已创建并同步','已在BitBrowser创建真实窗口，并完成Profile读回与Cloud镜像保存。')+objectStrip('B站新号 · 上海05','系统窗口 ID 346　·　BitBrowser序号 1036')+facts([['窗口名称','B站新号 · 上海05'],['BitBrowser分组','主力账号组'],['代理管理方式',badge('比特自管')],['当前代理','无代理 · 直连'],['账号绑定','尚未绑定媒体账号'],['最近同步','2026-10-27 14:36:12']])+notice('窗口已准备好，账号登录仍需由你完成','可以先配置代理，再绑定媒体账号并在窗口内人工登录。','green'),btn('返回列表','w-list')+btn('配置代理','w-mode','primary'))}
function editWindow(){return dialog('编辑BitBrowser窗口',objectStrip()+notice('仅修改下面提交的目标字段','保存前会读取当前实际配置；写入后读回对应字段。不会使用Cloud完整配置覆盖窗口。')+`<div class="form-grid">${field('窗口名称','B站主号 · 上海01',{full:true,required:true})}${field('BitBrowser分组','主力账号组',{options:['主力账号组','备用账号组','华南运营组']})}${field('BitBrowser标签','B站，华东')}${field('BitBrowser备注','专用创作窗口，请保持指纹配置不变。',{full:true,area:true})}</div><div class="read-only" style="margin-top:18px">${icon('LockOn')} 当前代理、指纹、Cookie和媒体账号关系不会随本次编辑改变。</div><div class="scene-hint">运营备注请在独立的「编辑运营备注」中维护，不写入BitBrowser。</div>`,cancel()+btn('保存并读回','!save-bit','primary'))}
function note(){return dialog('编辑运营备注',objectStrip()+`<div class="form-grid">${field('运营备注','每日发布前检查账号状态；请勿与测试窗口混用。',{area:true,full:true,hint:'保存到WT Media，供获授权的运营协作。不会写入BitBrowser，也不会被窗口同步覆盖。'})}</div><div class="read-only" style="margin-top:18px"><span class="subtle">BitBrowser备注（只读）</span><br>专用创作窗口，请保持指纹配置不变。</div>`,cancel()+btn('保存','!save-note','primary'))}
function editFailure(){return dialog('窗口修改结果待核实',resultHead('写入已发送，读回未完成','未能确认名称是否已在BitBrowser生效。当前Cloud镜像保持上次确认结果。','orange')+objectStrip()+facts([['本次目标字段','窗口名称'],['原确认值','B站主号 · 上海01'],['本次提交值','B站主号 · 上海01（主力）'],['未完成原因','读取Profile超时，无法确认实际结果']])+notice('请先核实当前实际值，不要直接重复保存','核实后只处理尚未生效的字段。其他窗口资料与账号关系保持原状。','orange'),btn('稍后处理','w-list')+btn('读取实际值并核实','w-uncertain','primary'))}
function partial(){return dialog('窗口修改结果',resultHead('部分字段已更新','已确认成功的字段无需再次提交；未完成项可单独处理。','orange')+`<div class="table-wrap"><table><thead><tr><th>目标字段</th><th>实际结果</th><th>状态</th></tr></thead><tbody><tr><td>窗口名称</td><td>B站主号 · 上海01（主力）</td><td>${badge('已读回一致','green')}</td></tr><tr><td>BitBrowser分组</td><td>主力账号组</td><td>${badge('已读回一致','green')}</td></tr><tr><td>BitBrowser备注</td><td>读取超时，结果待确认</td><td>${badge('待核实','orange')}</td></tr></tbody></table></div>`+notice('不会重复修改名称和分组','核实备注实际值后再决定是否需要重试。','orange'),btn('返回列表','w-list')+btn('核实未完成项','w-uncertain','primary'))}
function mode(){return dialog('代理管理方式',objectStrip('百度 · 上海02','系统窗口 ID 329　·　当前实际代理 198.51.100.24:8080')+`<div class="choice-list"><div class="choice"><strong>${badge('比特自管')}　当前方式</strong>代理由你在BitBrowser维护。WT Media只同步实际配置，不创建系统代理资源，也不占用系统额度。<div class="tiny muted" style="margin-top:7px">当前实际代理：http://198.51.100.24:8080</div></div><div class="choice"><strong>${badge('系统管理','blue')}</strong>从代理管理中选择资源，写入并读回一致后建立正式关系与配额占用。<br>${btn('选择系统代理','w-bind','primary')}</div></div>`,btn('关闭','!close'))}
