function scaleStage(){const wrap=document.getElementById('stage-wrap'),stage=document.getElementById('stage');const height=current?.module==='system'?1120:['p-detail-api','p-expired'].includes(current?.id)?1440:1320;stage.style.height=height+'px';document.documentElement.style.setProperty('--art-height',height+'px');if(document.body.classList.contains('export'))return;const scale=wrap.clientWidth/1600;stage.style.transform=`scale(${scale})`;wrap.style.height=`${height*scale}px`}
function go(id,push=true){const next=SCENES.find(s=>s.id===id)||SCENES[0];if(current)previous=current.id;current=next;formDirty=false;const q=new URLSearchParams(location.search);if(push&&location.protocol!=='about:'){q.set('scene',next.id);history.replaceState(null,'',location.pathname+'?'+q)}renderScene()}
function renderScene(){const s=current;let content;if(s.module==='system'){content=typeof componentBoard==='function'?componentBoard(s):listPage(SCENES[0])}else{content=listPage(s);if(s.view!=='list'&&typeof window[s.view]==='function')content+=window[s.view](s)}document.getElementById('stage').innerHTML=content;if(s.state==='offline'){document.querySelectorAll('#stage .row-actions button').forEach(b=>{if(b.textContent.trim()!=='详情')b.disabled=true});document.querySelectorAll('#stage .page-header .btn').forEach(b=>b.disabled=true)}document.getElementById('book-header').innerHTML=`<div><div class="book-title">${String(s.index).padStart(2,'0')} / ${SCENES.length}　${s.name}</div><div class="book-caption">${s.note}</div></div><div class="book-nav">${btn('‹ 上一屏','!previous')}${btn('下一屏 ›','!next')}</div>`;document.querySelectorAll('.catalog-item').forEach(n=>n.classList.toggle('active',n.dataset.go===s.id));document.getElementById('book-footer').innerHTML=`<span>起飞 · 运营资源体验优化　/　完整视觉方案 V1.0</span><span>目标产品视觉 · 示例数据 · 本地交互预览 · 2026.10.27</span>`;scaleStage()}
function showToast(message,tone='green'){document.querySelector('.toast')?.remove();const n=document.createElement('div');n.className='toast';n.innerHTML=icon(tone==='green'?'CheckCircle':'InfoCircle')+`<span>${e(message)}</span>`;document.getElementById('stage').appendChild(n);setTimeout(()=>n.remove(),3800)}
function filterRows(value,scope=document.getElementById('stage')){scope.querySelectorAll('tr[data-search]').forEach(tr=>tr.hidden=!tr.dataset.search.toLowerCase().includes(value.toLowerCase()))}
document.addEventListener('click',event=>{const target=event.target.closest('[data-go],[data-action]');if(!target||target.disabled)return;if(target.dataset.go){go(target.dataset.go);return}const action=target.dataset.action;if(typeof runAction==='function'){runAction(action,target);return}if(action==='close')go(current.module==='proxy'?'p-list':'w-list');else if(action==='previous')go(SCENES[(current.index-2+SCENES.length)%SCENES.length].id);else if(action==='next')go(SCENES[current.index%SCENES.length].id);else showToast('操作已记录到本地预览')});
document.addEventListener('input',event=>{formDirty=true;if(event.target.matches('[data-filter]'))filterRows(event.target.value);if(event.target.matches('[data-candidate-search]'))filterRows(event.target.value,event.target.closest('.dialog'))});
document.addEventListener('change',event=>{if(event.target.dataset.routeChange)go(event.target.dataset.routeChange);if(event.target.matches('input[type=radio][name=proxy-choice]')){event.target.closest('tbody').querySelectorAll('tr').forEach(n=>n.classList.remove('selected'));event.target.closest('tr').classList.add('selected')}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.querySelector('.overlay'))go(current.module==='proxy'?'p-list':'w-list')});
window.addEventListener('resize',scaleStage);
const groups=[...new Set(SCENES.map(s=>s.group))];document.getElementById('catalog').innerHTML=`<div class="book-brand">运营资源 · 视觉全案</div><div class="book-eyebrow">QIFEI / PRODUCT DESIGN</div><div class="book-count">${SCENES.length} 个完整场景<br>浏览器窗口 · 代理管理<br>列表 / 抽屉 / 弹窗 / 完整状态</div>${groups.map(g=>`<div class="catalog-group">${g}</div>${SCENES.filter(s=>s.group===g).map(s=>`<button class="catalog-item" data-go="${s.id}"><span class="catalog-num">${String(s.index).padStart(2,'0')}</span>${s.name}</button>`).join('')}`).join('')}`;
