function checking(s){const result=s.state==='result';return dialog('代理检测',result?resultHead('连接检测已完成','已保存本次检测时间和结果；不代表所有平台任务必然可执行。'):resultHead('正在检测代理连接','检测过程不改变窗口代理，也不占用系统额度。','orange'),cancel(),'compact').replace('</div><footer class="dialog-footer">',`<div class="object-strip"><span class="object-mark">${icon('Link')}</span><div><strong>沪线 · 静态03</strong><small>socks5://203.0.113.18:1080</small></div></div>${result?facts([['连接可达性',badge('正常','green')],['检测时间','2026-10-27 14:43:10'],['检测范围','代理连接可达性；平台与账号环境另行检查']]):`<div class="status-line"><span>连接可达性</span><span class="subtle">${'<span class="spin"></span>'} 检测中</span></div><div class="progress"><span style="width:65%"></span></div><div class="tiny muted">等待真实检测结果，不将请求已提交显示为检测正常。</div>`}</div><footer class="dialog-footer">`).replace(`${cancel()}</footer>`,result?`${btn('完成','p-list','primary')}</footer>`:`${btn('关闭','p-list')}${btn('查看检测结果','p-check-result','primary')}</footer>`)}
function batchCheck(){const rows=proxyRows.slice(0,6);return drawer('批量代理检测结果',resultHead('6条资源已处理','4条连接正常，1条检测失败，1条已到期跳过。','orange')+resultStats([[6,'总数 / 已完成'],[4,'正常'],[1,'失败'],[1,'跳过']])+`<table class="dense"><thead><tr><th>代理资源</th><th>结果</th><th>说明</th><th>操作</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${r[1]}<div class="mono muted">${r[3]}</div></td><td>${badge(i===2?'跳过':i===5?'失败':'正常',i===2?'':i===5?'red':'green')}</td><td class="tiny subtle">${i===2?'资源已到期，不参与检测':i===5?'连接超时，本次未确认可用':'连接可达，检测时间已更新'}</td><td>${i===5?btn('单独重试','p-checking','text'):'—'}</td></tr>`).join('')}</tbody></table>`+notice('连接检测与窗口写入相互独立','本次没有更改任何BitBrowser配置或正式绑定关系。'),btn('返回台账','p-list')+btn('重试失败项','p-checking','primary'),true)}
function deleteProxyView(s){const blocked=s.state==='blocked';return dialog(blocked?'暂时无法删除代理':'删除代理资源',objectStrip(blocked?'沪线 · 静态03':'沪线 · 测试01',blocked?'PX-003　·　存在3个绑定窗口':'PX-022　·　无绑定窗口、无历史引用','Link')+notice(blocked?'代理仍被窗口引用':'此操作将删除这条未使用的代理台账',blocked?'必须先在浏览器窗口中更换或解绑，并完成实际读回。这里不会远程修改窗口。':'只删除这条未使用资源；不会删除BitBrowser窗口或媒体账号。',blocked?'orange':'red')+(blocked?`<table><thead><tr><th>关联窗口</th><th>当前关系</th><th>入口</th></tr></thead><tbody>${['B站主号 · 上海01','百度 · 上海03','B站备用 · 上海04'].map(n=>`<tr><td>${n}</td><td>${badge('系统管理','blue')}</td><td>${btn('查看窗口','w-detail-managed','text')}</td></tr>`).join('')}</tbody></table>`:facts([['当前资源状态','停用'],['绑定窗口','0 个'],['历史引用','无'],['实际地址','203.0.113.122:1080']])) ,blocked?btn('知道了','p-list','primary'):cancel()+btn('删除代理','!delete-proxy','danger'),'compact')}
function pause(){return dialog('停用代理资源',objectStrip('沪线 · 静态03','PX-003　·　当前关联3个窗口','Link')+notice('停用后不再参与新的推荐和分配','不会自动清除已绑定窗口的实际代理。请按需要在窗口页处理现有使用情况。','orange')+facts([['资源状态','启用 → 停用'],['当前绑定窗口','3 个'],['已有配置','保留BitBrowser实际代理与Cloud正式关系'],['历史与资料','保留，之后可以重新启用']]),cancel()+btn('停用代理','!pause-proxy','primary'),'compact')}
window.delete=deleteProxyView;window.import=importProxy;

function componentBoard(s){if(s.view==='buttons')return `<div class="standalone-board"><h1>按钮与交互状态</h1><div class="description">同一套控件体系贯穿列表、抽屉与弹窗。配置可修改，结果只读展示；危险动作需要明确确认。</div><div class="state-grid"><section class="panel state-card"><h3>操作层级</h3><div class="component-row"><span class="component-label">主要操作</span>${btn('新建窗口','w-create','primary')}${btn('保存并读回','w-edit','primary')}</div><div class="component-row"><span class="component-label">常规操作</span>${btn('同步本机窗口','w-sync')}${btn('取消','w-list')}</div><div class="component-row"><span class="component-label">行内操作</span>${btn('详情','w-detail-managed','text')}${btn('编辑','w-edit','text')}${btn('管理代理','w-mode','text')}</div><div class="component-row"><span class="component-label">危险操作</span>${btn('删除代理','p-delete','danger')}${btn('解绑并改直连','w-unbind','text danger-text')}</div><div class="component-row"><span class="component-label">不可执行</span>${btn('打开窗口','','',true)}<span class="tiny subtle">原因：本机窗口缺失</span></div><div class="component-row"><span class="component-label">请求处理中</span>${btn('<span class="spin"></span> 保存中…','','primary',true)}<span class="tiny subtle">防止重复提交</span></div></section><section class="panel state-card"><h3>配置与事实分离</h3><div class="component-row"><span class="component-label">业务启停配置</span><button class="switch" data-go="w-disable" aria-label="停用窗口"></button><span>启用</span><button class="switch off" data-action="enable" aria-label="启用窗口"></button><span>停用</span></div><div class="component-row"><span class="component-label">登录与环境事实</span>${badge('登录正常','green')}${badge('环境异常','red')}${badge('未检查')}</div><div class="component-row"><span class="component-label">配置差异</span>${badge('代理配置不一致','orange')}${btn('处理','w-mismatch','text')}</div><div class="component-row"><span class="component-label">配额</span><span>3 / 8</span><span class="tiny muted">剩余5个窗口</span>${btn('设置配额','p-quota','text')}</div><div class="component-row"><span class="component-label">敏感输入</span><input type="password" class="input" value="example-only-secret" style="width:190px" aria-label="代理密码"></div><div class="state-note">控件只承担一个明确语义；状态Badge不做伪按钮。普通配置确认使用主按钮，真实删除或清除代理使用危险语义。</div></section><section class="panel state-card"><h3>完整反馈</h3>${notice('保存成功','仅在真实结果读回并保存后显示。','green')}${notice('当前环境不可用','持续状态靠近相关内容，不使用短Toast代替。','orange')}${notice('操作失败','说明未完成部分与可采取的下一步。','red')}<div class="field"><label>字段校验</label><input class="input error" value="2" aria-label="错误配额示例"><div class="error-text">不能小于当前已占用的3个窗口。</div></div></section><section class="panel state-card"><h3>确认与结果</h3><div class="choice-list"><div class="choice"><strong>配置变更确认</strong>说清对象、目标值与影响。${btn('查看启停确认','w-disable','text')}</div><div class="choice"><strong>外部写入</strong>请求完成不等于配置生效，必须核对实际值。${btn('查看读回失败','w-edit-failed','text')}</div><div class="choice"><strong>结果待确认</strong>先核实，不盲目重试。${btn('查看核实流程','w-uncertain','text')}</div></div></section></div></div>`;
return `<div class="standalone-board"><h1>状态、字段与信息规范</h1><div class="description">管理意图、外部事实和业务配置分别表达，避免让运营把一种状态误解成另一种状态。</div><div class="state-grid"><section class="panel state-card"><h3>代理管理方式 ≠ 代理来源</h3><div class="component-row"><span class="component-label">管理方式</span>${badge('比特自管')}${badge('系统管理','blue')}</div><div class="component-row"><span class="component-label">资源来源</span>${badge('静态地址')}${badge('动态 API','blue')}</div><div class="state-note">同一系统代理资源可以来自静态地址或API；比特自管则只同步实际配置，不自动建立资源台账。</div><div class="divider"></div><h3>两类备注、两类标签</h3><div class="component-row"><span class="component-label">BitBrowser备注</span><span>创作专用窗口，保留当前指纹</span></div><div class="component-row"><span class="component-label">运营备注</span><span>周一检查，异常由当班运营处理</span></div><div class="component-row"><span class="component-label">BitBrowser标签</span>${tags(['B站','华东'],true)}</div><div class="component-row"><span class="component-label">WT Media标签</span>${tags(['主力运营','日常发布'])}</div></section><section class="panel state-card"><h3>窗口事实</h3><div class="component-row"><span class="component-label">存在性</span>${badge('本机存在','green')}${badge('本机窗口缺失','red')}</div><div class="component-row"><span class="component-label">运行状态</span>${badge('已打开','green',true)}${badge('已关闭')}${badge('未知')}</div><div class="component-row"><span class="component-label">业务配置</span>${badge('启用','green')}${badge('停用')}</div><div class="component-row"><span class="component-label">代理一致性</span>${badge('已读回一致','green')}${badge('配置不一致','orange')}</div><div class="component-row"><span class="component-label">操作结果</span>${badge('已完成','green')}${badge('失败','red')}${badge('待核实','orange')}${badge('跳过')}</div><div class="state-note">窗口已打开不代表账号已登录；代理有地址不代表资源有效；同步完成不代表所有异常都已解决。</div></section><section class="panel state-card"><h3>资源治理状态</h3><div class="component-row"><span class="component-label">运营状态</span>${badge('启用','green')}${badge('停用')}${badge('已到期','red')}</div><div class="component-row"><span class="component-label">检测状态</span>${badge('尚未检测')}${badge('检测中','blue')}${badge('连接正常','green')}${badge('检测失败','red')}</div><div class="component-row"><span class="component-label">配额</span>${badge('可分配','green')}${badge('配额已满','orange')}</div><div class="state-note">已停用、到期、未检测或检测失败的资源不可作为新的系统绑定候选。状态说明与禁用原因就近展示。</div></section><section class="panel state-card"><h3>状态反馈与空态</h3><div class="choice-list"><div class="choice"><strong>无数据 / 筛选无结果</strong>分别给出新增、同步或清除筛选入口。${btn('查看空态','s-empty','text')}</div><div class="choice"><strong>加载失败 / 无权限</strong>清楚说明原因，不用「暂无数据」掩盖。${btn('查看失败态','s-error','text')}${btn('查看权限态','s-permission','text')}</div><div class="choice"><strong>Cloud Web / Desktop</strong>显示环境差异，隐藏无权执行的本机动作。${btn('查看Web边界','w-web','text')}</div></div></section></div></div>`}

function runAction(action,target){const base=current.module==='proxy'?'p-list':'w-list';
if(action==='close'){const back=SCENES.find(s=>s.id===previous);go(back&&back.module===current.module&&back.id!==current.id?back.id:base);return}
if(action==='previous'||action==='next'){go(SCENES[(current.index+(action==='next'?0:-2)+SCENES.length)%SCENES.length].id);return}
if(action==='select'){go('w-batch');return}
if(action==='select-proxy'){if(!document.querySelector('#stage .selection')){const bar=document.createElement('div');bar.className='selection';bar.innerHTML='<span>已选择代理资源 · 检测仍按单条规则执行</span>'+btn('批量检测','p-batch-check','small');document.querySelector('#stage .table-wrap').before(bar)}return}
if(action==='filter'){const filters=document.querySelector('#stage .filters');const search=filters.querySelector('[data-filter]').value.trim();const values=[...filters.querySelectorAll('select')].map(n=>n.value).filter(v=>v!=='全部');const map={'比特自管':'self','系统管理':'system','代理配置不一致':'mismatch','代理到期':'expired','本机缺失':'missing','启用':'ok','停用':'paused','已到期':'expired'};document.querySelectorAll('#stage tr[data-search]').forEach(tr=>tr.hidden=![search,...values.map(v=>map[v]||v)].every(v=>tr.dataset.search.toLowerCase().includes(v.toLowerCase())));return}
if(action==='create-window'||action==='save-bit'){const inputs=[...document.querySelectorAll('.dialog input[required]')];let invalid=false;inputs.forEach(n=>{if(!n.value.trim()){n.classList.add('error');if(!n.parentNode.querySelector('.error-text'))n.insertAdjacentHTML('afterend','<div class="error-text">请填写此项。</div>');invalid=true}});if(invalid)return;go(action==='create-window'?'w-create-success':'w-list');showToast(action==='create-window'?'窗口已创建并同步':'目标字段已写入、读回并同步');return}
if(action==='save-note'){go(base);showToast('运营备注已保存，BitBrowser备注保持不变');return}
if(['bind-proxy','replace-proxy','resync-proxy','unbind-proxy','verify-result'].includes(action)){go('w-list');showToast(action==='unbind-proxy'?'已读回直连配置，系统关系与额度已解除':action==='verify-result'?'实际结果已核实，已按真实配置收敛':'代理写入与读回一致，正式关系已更新');return}
if(action==='save-bound-proxy'){go('p-list');showToast('资料已保存；3个关联窗口需要重新同步代理配置','orange');return}
if(action==='save-proxy'){go('p-list');showToast('代理资料已保存，尚未自动修改任何窗口');return}
if(action==='save-quota'){const n=document.querySelector('.dialog input');if(Number(n.value)<3){go('p-quota-error');return}go('p-list');showToast('窗口配额已保存');return}
if(action==='parse-proxy'){showToast('地址已解析，连接字段已回填');return}
if(action==='disable-window'||action==='enable'){go('w-list');showToast(action==='enable'?'窗口已启用':'窗口已停用，资料和历史保留');return}
if(action==='pause-proxy'){go('p-list');showToast('代理已停用，已有BitBrowser配置未被改写');return}
if(action==='delete-proxy'){go('p-list');showToast('未被引用的代理资源已删除');return}
if(action==='assign-owner'){go('w-web');showToast('Cloud窗口授权已更新，未执行本机操作');return}
if(action==='window'){showToast(target.textContent.includes('关闭')?'窗口已关闭并确认':'窗口已打开，平台登录仍由你在窗口内完成');return}
if(action==='more-window'){document.querySelector('.popup-menu')?.remove();const pop=document.createElement('div');pop.className='popup-menu';pop.style.cssText='position:absolute;right:25px;top:455px;z-index:15;width:190px;padding:8px;background:#fff;border:1px solid var(--line);border-radius:6px;box-shadow:var(--popup)';pop.innerHTML=[['编辑BitBrowser字段','w-edit'],['编辑运营备注','w-note'],['更换系统代理','w-replace'],['解绑并改为直连','w-unbind'],['停用窗口','w-disable']].map(([l,t])=>`<div style="padding:5px">${btn(l,t,'text')}</div>`).join('');document.getElementById('stage').appendChild(pop);return}
if(action==='choose-file'){document.getElementById('import-file').click();return}
if(action==='download-template'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['名称,协议,Host,Port,用户名,密码,地区,供应商,最大窗口数,备注\n示例代理,socks5,203.0.113.128,1080,,,上海,示例供应商,3,示例资料\n'],{type:'text/csv;charset=utf-8;'}));a.download='代理导入标准模板.csv';a.click();URL.revokeObjectURL(a.href);showToast('标准模板已导出');return}
if(action==='fix-import'){const tr=target.closest('tr');tr.innerHTML='<td><input type="checkbox" class="check" checked></td><td>6</td><td><input class="input" value="203.0.113.132:1080" aria-label="修正代理地址"></td><td>无</td><td>'+badge('已修正','green')+'</td><td>'+btn('重新解析','!parse-proxy','text')+'</td>';return}
if(action==='sync-unchanged'){document.querySelectorAll('.tab').forEach(n=>n.classList.remove('active'));target.classList.add('active');const table=target.closest('.drawer-body').querySelector('.table-wrap');if(table)table.innerHTML='<table><thead><tr><th>窗口</th><th>结果</th></tr></thead><tbody>'+windowRows.slice(0,5).map(r=>'<tr><td>'+r[1]+'</td><td>'+badge('实际配置未变化','green')+'</td></tr>').join('')+'</tbody></table>';return}
if(action==='page'){document.querySelectorAll('.page-number').forEach(n=>n.classList.remove('selected'));target.classList.add('selected');showToast('已切换列表页码示例');return}
if(action==='home'){go('w-list');return}
showToast('当前操作已在视觉预览中完成')}
renderScene();
